//Otra vez, extensión de modulo
public class ModuloEnergia extends Modulo {
//Protected por buena práctica, pero pudieron ser private
    protected int energiaGenerada;
    protected int ciclosEnergia;

//Constructor vacío
    public ModuloEnergia() {
		//Super, ir a Modulo
        super();
        energiaGenerada = 0;
        ciclosEnergia = 0;
    }

//Constructor NO vacío
    public ModuloEnergia(String id, String nombre, int salud,boolean activo, int clase, float costo, int energiaGenerada, int ciclosEnergia) {
		//Llamo los que necesito
        super(id, nombre, salud, activo, clase, costo);
		//Los nuevos
        this.energiaGenerada = energiaGenerada;
        this.ciclosEnergia = ciclosEnergia;
    }

//Setters y getter - otra vez
//Espero que estos sean obvios de por que estan acá

    public void setEnergiaGenerada(int newEnergiaGenerada) {
        energiaGenerada = newEnergiaGenerada;
    }

    public int getEnergiaGenerada() {
        return energiaGenerada;
    }


    public void setCiclosEnergia(int newCiclosEnergia) {
        ciclosEnergia = newCiclosEnergia;
    }

    public int getCiclosEnergia() {
        return ciclosEnergia;
    }


    @Override
	//Otra vez, el procesoCiclo depende del Modulo, asi que:
    public void procesoCiclo(Mision mision) {
		//¿Esta activo?
        if (!activo) {
            System.out.println(nombre + " no operó porque está inactivo.");
		//Como este NO GASTA ENERGÍA, no debo verificar eso, de una empiezo a codificar:
        } else {
            mision.setEnergiaDisponible(mision.getEnergiaDisponible() + energiaGenerada);

			//Aumentar un ciclo más
            ciclosEnergia++;

			//Mensaje
            System.out.println(nombre + " generó "+ energiaGenerada+ " unidades de energía.");
        }
    }


    @Override
	//Características exclusivas
    public void mostrarCaracteristicas() {
		// ... ¿Qué pocas cosas hay que agregar esta vez, no? Que sencillo...
        System.out.println("Energía generada por ciclo: " + energiaGenerada);
        System.out.println("Ciclos de energía: " + ciclosEnergia);
    }
}